import { z } from '@daz-pilot/daz-pilot-backend-api-types';

export const environmentSchema = z.enum(['development', 'testing', 'production']);

const literalSchema = z.union([z.string(), z.number(), z.boolean(), z.null()]);

type Literal = z.infer<typeof literalSchema>;

export type Json = Literal | { [key: string]: Json } | Json[];

export const jsonSchema: z.ZodType<Json> = z.lazy(() =>
	z.union([literalSchema, z.array(jsonSchema), z.record(z.string(), jsonSchema)]),
);

export const portSchema = z.coerce
	.number()
	.int()
	.min(0)
	.max(2 ** 16 - 1);

export const buffer32Schema = z.custom<Buffer>((value) => value instanceof Buffer && value.length === 32, {
	message: 'Must be exactly 32 bytes long',
});

export type Buffer32 = z.infer<typeof buffer32Schema>;

export const booleanSchema = z
	.union([z.boolean(), z.number(), z.string()])
	.transform((value): boolean => {
		if (typeof value === 'number') {
			if (value === 1) {
				return true;
			}
			if (value === 0) {
				return false;
			}
			return value as unknown as boolean;
		}
		if (typeof value === 'string') {
			switch (value.toLowerCase()) {
				case 'true':
				case '1':
					return true;
				case 'false':
				case '0':
					return false;
				default:
					return value as unknown as boolean;
			}
		}
		return value;
	})
	.refine((value) => typeof value === 'boolean', { message: 'Invalid boolean' });

